CREATE TABLE CPF_RUNTIME_INSTANCE_HEALTH (SYSTEM_ID VARCHAR(64) NOT NULL, INSTANCE_ID VARCHAR(128) NOT NULL, VERSION VARCHAR(64), BUILD_SHA VARCHAR(64), STARTED_AT TIMESTAMP WITH TIME ZONE NOT NULL, UPTIME_MS BIGINT NOT NULL, LAST_SEEN_AT TIMESTAMP WITH TIME ZONE NOT NULL, LIVENESS VARCHAR(32) NOT NULL, READINESS VARCHAR(32) NOT NULL, STARTUP VARCHAR(32) NOT NULL, DRAINING SMALLINT NOT NULL DEFAULT 0, MAINTENANCE SMALLINT NOT NULL DEFAULT 0, PAYLOAD_JSON TEXT NOT NULL, PRIMARY KEY(SYSTEM_ID,INSTANCE_ID));
CREATE INDEX IX_CPF_RIH_LAST_SEEN ON CPF_RUNTIME_INSTANCE_HEALTH(LAST_SEEN_AT);
CREATE INDEX IX_CPF_RIH_READINESS ON CPF_RUNTIME_INSTANCE_HEALTH(READINESS,LAST_SEEN_AT);
